import{mkdir,readFile,readdir,rm,writeFile}from"node:fs/promises";import{join}from"node:path";const OWNER_FILE_NAME=`owner.json`;async function createEvalStateDirectory(e,t){let n=join(e,`.eve`,`eval-servers`);await removeAbandonedEvalStateDirectories(n);let r=join(n,t);return await mkdir(r,{recursive:!0}),await writeFile(join(r,OWNER_FILE_NAME),JSON.stringify({pid:process.pid})),r}async function removeEvalStateDirectory(e){await rm(e,{force:!0,recursive:!0,maxRetries:5,retryDelay:100})}async function removeAbandonedEvalStateDirectories(e){let t;try{t=await readdir(e)}catch{return}await Promise.all(t.map(async t=>{let n=join(e,t),r=await readOwnerPid(n);r===void 0||isProcessAlive(r)||await removeEvalStateDirectory(n).catch(()=>{})}))}async function readOwnerPid(e){try{let t=JSON.parse(await readFile(join(e,OWNER_FILE_NAME),`utf8`));return typeof t.pid==`number`&&Number.isInteger(t.pid)&&t.pid>0?t.pid:void 0}catch{return}}function isProcessAlive(e){try{return process.kill(e,0),!0}catch(e){return e instanceof Error&&`code`in e&&e.code===`EPERM`}}export{createEvalStateDirectory,removeEvalStateDirectory};